fn('loadFont', "async function loadFont(name){if(!name)return;if(!fontLinks.has(name)){fontLinks.set(name,(async()=>{const m=fontMeta(name),google='https://fonts.googleapis.com/css2?family='+encodeURIComponent(name).replace(/%20/g,'+')+'&display=swap',cdn=m.id?'https://cdn.jsdelivr.net/npm/@fontsource/'+encodeURIComponent(m.id)+'/400.css':null;for(const url of [google,cdn].filter(Boolean)){const link=document.createElement('link');link.rel='stylesheet';link.href=url;const ready=new Promise(resolve=>{link.onload=()=>resolve(true);link.onerror=()=>resolve(false);setTimeout(()=>resolve(false),5000)});document.head.append(link);if(await ready){try{const faces=await Promise.race([document.fonts.load('100px '+JSON.stringify(name)),new Promise(resolve=>setTimeout(()=>resolve([]),5000))]);if(faces.length){loadedFonts.add(name);return true}}catch(e){}}link.remove()}if(name===state.font)$('fontLoadStatus').textContent='Il font '+name+' non è scaricabile: verifica il filtro di rete. Il catalogo resta completo; viene usato il carattere di sistema.';fontLinks.delete(name);return false})())}return fontLinks.get(name)}")
