bat=(root/'OutlineLab_v5_server.bat').read_text().replace('OutlineLab_v5.html','chicCanva.html').replace('OutlineLab v5','chicCanva').replace('OutlineLab:','chicCanva:')
(root/'chicCanva_server.bat').write_text(bat,encoding='utf-8',newline='\r\n')
build=root/'build/chicCanva';build.mkdir(parents=True,exist_ok=True)
for f in ['chicCanva.html','chicCanva_server.bat']:shutil.copy2(root/f,build/f)
